trait SN_Future_Superset_Part_3 {
    public static function call_lobby(WP_REST_Request $r): WP_REST_Response|WP_Error {$call=absint($r['id']);$u=get_current_user_id();if(!self::call_member($call,$u))return self::not_found();return rest_ensure_response(['call_id'=>$call,'lobby'=>self::scope('F17-FUT-17','call',$call)]);}
    public static function update_call_lobby(WP_REST_Request $r): WP_REST_Response|WP_Error {$call=absint($r['id']);$actor=get_current_user_id();if(!self::call_manager($call,$actor))return self::error('forbidden','Call host permission is required.',403);$target=absint($r->get_param('user_id'));if(!$target||!self::call_member($call,$target))return self::error('sn_lobby_member_invalid','Select an active call member.',409);$state=self::enum((string)$r->get_param('state'),['waiting','admitted','rejected'],'waiting');$id=self::upsert_record('F17-FUT-17',$target,'call',$call,['user_id'=>$target,'state'=>$state,'moderated_by'=>$actor],'lobby:'.$call.':'.$target,null);return is_wp_error($id)?$id:rest_ensure_response(['call_id'=>$call,'user_id'=>$target,'state'=>$state]);}
    public static function hand_raise(WP_REST_Request $r): WP_REST_Response|WP_Error {$call=absint($r['id']);$u=get_current_user_id();if(!self::call_member($call,$u))return self::not_found();$raised=rest_sanitize_boolean($r->get_param('raised'));$id=self::upsert_record('F17-FUT-18',$u,'call',$call,['user_id'=>$u,'raised'=>$raised,'at'=>self::now()],'hand:'.$call.':'.$u,null);return is_wp_error($id)?$id:rest_ensure_response(['call_id'=>$call,'raised'=>$raised]);}
    public static function create_breakouts(WP_REST_Request $r): WP_REST_Response|WP_Error {$call=absint($r['id']);$u=get_current_user_id();if(!self::call_manager($call,$u))return self::error('forbidden','Call host permission is required.',403);$rooms=is_array($r->get_param('rooms'))?$r->get_param('rooms'):[];if(!$rooms||count($rooms)>20)return self::error('sn_breakouts_invalid','Provide 1 to 20 breakout rooms.',400);$clean=[];foreach($rooms as $room){$name=mb_substr(sanitize_text_field((string)($room['name']??'')),0,100);$users=array_values(array_unique(array_filter(array_map('absint',(array)($room['user_ids']??[])))));if($name===''||!$users)return self::error('sn_breakout_room_invalid','Each breakout room needs name and participants.',400);foreach($users as $x)if(!self::call_member($call,$x))return self::error('sn_breakout_participant_invalid','Every breakout participant must be an active call member.',409);$clean[]=['name'=>$name,'user_ids'=>$users];}$provider=apply_filters('sn_network_breakout_create_result',null,$call,$clean,$u);if($provider===null)return self::error('sn_breakout_provider_unavailable','Breakout rooms require an approved SFU adapter.',503);if(is_wp_error($provider))return $provider;$id=self::upsert_record('F17-FUT-19',0,'call',$call,['rooms'=>$clean,'provider_result_hash'=>hash('sha256',wp_json_encode($provider))],'breakouts:'.$call,null);return is_wp_error($id)?$id:rest_ensure_response(['call_id'=>$call,'rooms'=>$clean,'provider'=>$provider]);}
    public static function transfer_call_host(WP_REST_Request $r): WP_REST_Response|WP_Error {$call=absint($r['id']);$u=get_current_user_id();if(!self::call_manager($call,$u))return self::error('forbidden','Current host permission is required.',403);$target=absint($r->get_param('user_id'));if(!$target||!self::call_member($call,$target))return self::error('sn_call_host_invalid','Select an active call member.',409);$provider=apply_filters('sn_network_call_host_transfer_result',null,$call,$u,$target);if($provider===null||$provider===false)return self::error('sn_call_host_transfer_unavailable','Host transfer requires an approved conference adapter.',503);if(is_wp_error($provider))return $provider;$id=self::upsert_record('F17-FUT-20',0,'call',$call,['host_id'=>$target,'transferred_by'=>$u],'host:'.$call,null);return is_wp_error($id)?$id:rest_ensure_response(['call_id'=>$call,'host_id'=>$target]);}
    public static function network_quality(WP_REST_Request $r): WP_REST_Response|WP_Error {$call=absint($r['id']);$u=get_current_user_id();if(!self::call_member($call,$u))return self::not_found();$loss=max(0,min(100,(float)$r->get_param('packet_loss_pct')));$rtt=max(0,min(5000,absint($r->get_param('rtt_ms'))));$jitter=max(0,min(5000,absint($r->get_param('jitter_ms'))));$down=max(0,min(1000000,absint($r->get_param('downlink_kbps'))));$q=$loss>=8||$rtt>=700?'poor':($loss>=3||$rtt>=350?'fair':'good');$h=$q==='poor'?['prefer_audio_only'=>true,'reduce_video_resolution'=>true,'retry_ice'=>true]:($q==='fair'?['reduce_video_resolution'=>true]:[]);$id=self::upsert_record('F17-FUT-21',$u,'call',$call,['quality'=>$q,'packet_loss_pct'=>round($loss,2),'rtt_ms'=>$rtt,'jitter_ms'=>$jitter,'downlink_bucket'=>self::bandwidth_bucket($down)],'quality:'.$call.':'.$u,null);return is_wp_error($id)?$id:rest_ensure_response(['quality'=>$q,'hints'=>$h]);}
    public static function ai_assistant(WP_REST_Request $r): WP_REST_Response|WP_Error {$u=get_current_user_id();$c=absint($r->get_param('conversation_id'));if(!self::conversation_member($c,$u))return self::not_found();if(!rest_sanitize_boolean($r->get_param('explicit_consent')))return self::error('sn_ai_consent_required','Explicit per-request consent is required.',400);$ids=self::selected_message_ids($r,$c);if(is_wp_error($ids))return $ids;$messages=self::plain_messages($ids,$c);if(is_wp_error($messages))return $messages;$task=self::enum((string)$r->get_param('task'),['summary','draft','action_items','explain'],'summary');$res=apply_filters('sn_network_ai_assistant_result',null,['task'=>$task,'messages'=>$messages,'conversation_id'=>$c,'user_id'=>$u]);foreach($messages as &$m)$m['body']='';unset($m);if($res===null)return self::error('sn_ai_provider_unavailable','AI assistance requires the approved File 16 adapter.',503);if(is_wp_error($res))return $res;SN_DB::audit('future_ai_assistant','conversation',$c,'success',['task'=>$task,'selected_count'=>count($ids)],$u);return rest_ensure_response(['task'=>$task,'result'=>$res,'stored_by_file17'=>false]);}
    public static function semantic_search(WP_REST_Request $r): WP_REST_Response|WP_Error {$u=get_current_user_id();$c=absint($r->get_param('conversation_id'));if(!self::conversation_member($c,$u))return self::not_found();$q=mb_substr(sanitize_text_field((string)$r->get_param('query')),0,500);if(mb_strlen($q)<2)return self::error('sn_semantic_query_invalid','Enter a longer search query.',400);$res=apply_filters('sn_network_private_semantic_search_result',null,$q,$c,$u);if($res===null)return self::error('sn_semantic_provider_unavailable','Private semantic search requires an approved File-17 private-search adapter.',503);if(is_wp_error($res))return $res;$ids=array_slice(array_values(array_unique(array_filter(array_map('absint',(array)($res['message_ids']??$res))))),0,50);$out=[];foreach($ids as $id){$m=self::message_row($id);if(!$m||(int)$m->conversation_id!==$c||$m->deleted_at)continue;$p=SN_Message_Body::decrypt_row($m);if(!is_wp_error($p))$out[]=['message_id'=>$id,'snippet'=>mb_substr($p,0,500),'created_at'=>(string)$m->created_at];}return rest_ensure_response(['items'=>$out,'owner'=>'file-17','exported_to_file26'=>false]);}
    public static function create_interop_bridge(WP_REST_Request $r): WP_REST_Response|WP_Error {$u=get_current_user_id();$c=absint($r->get_param('conversation_id'));if(!self::conversation_manager($c,$u)&&!current_user_can('manage_options'))return self::error('forbidden','Conversation management permission is required.',403);$protocol=self::enum((string)$r->get_param('protocol'),['matrix','activitypub','custom-approved'],'matrix');$remote=esc_url_raw((string)$r->get_param('remote_endpoint'),['https']);if(!$remote||wp_parse_url($remote,PHP_URL_SCHEME)!=='https')return self::error('sn_interop_endpoint_invalid','A secure HTTPS endpoint is required.',400);if(!(bool)apply_filters('sn_network_interop_remote_allowed',false,$remote,$protocol,$c,$u)||!(bool)apply_filters('sn_network_interop_provider_ready',false,$protocol,$c,$u))return self::error('sn_interop_not_approved','Interoperability provider/destination is not approved.',503);$ref=mb_substr(sanitize_text_field((string)$r->get_param('credential_ref')),0,191);if(preg_match('/(bearer|password|secret|token=)/i',$ref))return self::error('sn_interop_secret_ref_invalid','Store only an opaque credential reference, never a secret.',400);$d=['protocol'=>$protocol,'remote_endpoint'=>$remote,'remote_room'=>mb_substr(sanitize_text_field((string)$r->get_param('remote_room')),0,191),'credential_ref'=>$ref,'direction'=>self::enum((string)$r->get_param('direction'),['outbound','bidirectional'],'outbound'),'identity_authority'=>'file-00/02-local'];$id=self::create_record('F17-FUT-24',$u,'conversation',$c,$d,self::client($r,$u,'interop'),null);if(is_wp_error($id))return $id;do_action('sn_network_interop_bridge_registered',$id,$d,$c,$u);return new WP_REST_Response(['id'=>$id,'bridge'=>$d],201);}
    public static function list_interop_bridges(): WP_REST_Response {return rest_ensure_response(['items'=>self::owned('F17-FUT-24',get_current_user_id())]);}
    public static function delete_owned_record(WP_REST_Request $r): WP_REST_Response|WP_Error {global $wpdb;$id=absint($r['id']);$u=get_current_user_id();$row=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.self::records_table().' WHERE id=%d AND owner_id=%d',$id,$u));if(!$row)return self::not_found();$ok=$wpdb->update(self::records_table(),['state'=>'deleted','updated_at'=>self::now(),'version'=>(int)$row->version+1],['id'=>$id,'version'=>(int)$row->version]);return $ok===1?rest_ensure_response(['deleted'=>true]):self::error('sn_record_conflict','Record changed before deletion.',409);}
